/* Source: src/tokens.css */
/* 昼夜之间 · 主聊天切片；色值来自批准概念图。 */
@font-face{font-family:'Noto Serif SC';src:url('https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notoserifsc/notoserifsc.woff2') format('woff2');font-weight:200 900;font-style:normal;font-display:swap;}
@font-face{font-family:'Ma Shan Zheng';src:url('https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/mashanzheng/mashanzheng.woff2') format('woff2');font-weight:400;font-style:normal;font-display:swap;}
:root {
 --zy-night:#101c29;
 --zy-blue:#294e76;
 --zy-ink:#12365b;
 --zy-muted:#49647b;
 --zy-paper:#fff5e4;
 --zy-yellow:#ffe5a8;
 --zy-apricot:#fa913f;
 --zy-edge:#e8b677;
 --zy-focus:#bd5a24;
 --zy-font:'Noto Serif SC','Source Han Serif SC','SimSun',serif;
 --zy-title:'Ma Shan Zheng','KaiTi','STKaiti',serif;
 --zy-avatar:2.6rem;
 --zy-avatar-gap:.85rem;
 --zy-avatar-slot:calc(var(--zy-avatar) + var(--zy-avatar-gap));
 --st-theme-mobile-reading-width:42rem;
 --st-theme-mobile-reading-padding:.2rem;
 --topBarIconSize:1.7rem;
 --topBarBlockPadding:1.2rem;
 --bottomFormIconSize:1.65rem;
 --bottomFormBlockPadding:.7rem;
}


/* Source: src/kernel/scrollbars.css */
/*
 * v7 固定全局无滚动条外观内核。
 * 只隐藏浏览器滚动条外观，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 * 全局 * 是本项目唯一允许的无边界选择器例外，不得增加其他声明。
 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}


/* Source: src/chat-layout.css */
/* 平滑色面为切片占位；手绘菱格与纸纹在布局确认后接入图片。 */
#bg1 { background:var(--zy-blue)!important; }
#sheld { background:var(--zy-night); }
#chat { background:var(--zy-night);backdrop-filter:none;-webkit-backdrop-filter:none;text-shadow:none;padding:1.5rem .9rem 1rem;gap:1.65rem;min-height:0; }
#chat .mes[is_system="false"] { flex:0 0 auto;gap:var(--zy-avatar-gap);padding:1.6rem clamp(1rem,2.3vw,2.8rem) 2rem;background:var(--zy-paper);color:var(--zy-ink);border:3px solid var(--zy-yellow);border-radius:8% 5% 9% 4% / 2.8rem 3.3rem 2.7rem 2.2rem;box-shadow:0 3px 0 var(--zy-edge); }
#chat .mes[is_user="true"][is_system="false"] { inline-size:min(78%,44rem);margin-inline-start:auto;background:var(--zy-yellow);border-color:var(--zy-paper);border-radius:3.2rem 2rem 3rem 2.1rem;padding-block:1.1rem 1.4rem; }
#chat .mes[is_system="false"] > .mesAvatarWrapper { flex:0 0 var(--zy-avatar);inline-size:var(--zy-avatar);color:var(--zy-muted); }
#chat .mes[is_system="false"] > .mesAvatarWrapper .avatar,
#chat .mes[is_system="false"] > .mesAvatarWrapper .avatar img { inline-size:var(--zy-avatar);block-size:var(--zy-avatar);border-radius:50%;box-shadow:none; }
#chat .mes[is_system="false"] > .mesAvatarWrapper .avatar { outline:2px solid var(--zy-edge); }
#chat .mes[is_system="false"] > .mes_block { flex:1 1 auto;min-inline-size:0;inline-size:auto;padding:0; }
#chat .mes .ch_name { gap:.65rem;flex-wrap:wrap;margin-block-end:.75rem; }
#chat .mes .name_text { font-family:var(--zy-title);font-size:1.65em;font-weight:400;color:var(--zy-ink); }
#chat .mes .timestamp { font-family:var(--zy-font);font-size:.78em;font-weight:500;color:var(--zy-muted);opacity:1; }
#chat .mes .mes_buttons { flex-wrap:wrap; }
#chat .mes .mes_button,
#chat .mes .swipe_left,
#chat .mes .swipe_right,
#chat .mes .swipes-counter { color:var(--zy-ink);opacity:1;filter:none;text-shadow:none; }
#chat .mes .mes_button:hover { color:var(--zy-focus); }
#chat .mes .mes_button:focus-visible,
#chat .mes .swipe_left:focus-visible,
#chat .mes .swipe_right:focus-visible { outline:2px solid var(--zy-focus);outline-offset:2px; }
#chat .mes[is_system="true"] { background:var(--zy-paper);color:var(--zy-ink);border-radius:1rem;padding:1rem; }
#chat .mes.selected { background:var(--zy-yellow);outline:3px solid var(--zy-focus);outline-offset:-3px; }
@media(max-width:700px) {
 #chat { padding:.85rem .4rem;gap:1.1rem; }
 #chat .mes[is_system="false"] { flex-direction:column;align-items:stretch;inline-size:100%;padding:1rem .85rem 1.7rem;gap:.6rem;border-width:2px;border-radius:1.8rem 1.2rem 2rem 1.4rem; }
 #chat .mes[is_system="false"] > .mesAvatarWrapper { flex:0 0 auto;align-self:center;margin-inline:auto; }
 #chat .mes[is_system="false"] > .mes_block { inline-size:100%;min-inline-size:0; }
 #chat .mes[is_system="false"] > .mes_block > .mes_text { inline-size:min(100%,var(--st-theme-mobile-reading-width));max-inline-size:100%;margin-inline:auto!important;padding-inline:var(--st-theme-mobile-reading-padding)!important;box-sizing:border-box; }
 #chat .mes .name_text { font-size:1.4em; }
}


/* Source: src/full-text.css */
#chat .mes_text { font-family:var(--zy-font);font-size:1em;font-weight:600;line-height:1.95;color:var(--zy-ink);margin-inline:auto;padding:.2rem 0;overflow-wrap:anywhere;text-shadow:none; }
#chat .mes_text p { margin-block:.3em 1.1em; }
#chat .mes_text strong,
#chat .mes_text b { font-weight:800;color:var(--zy-ink); }
#chat .mes_text em,
#chat .mes_text i:not([class*="fa-"]) { color:var(--zy-muted); }
#chat .mes_text q { color:var(--zy-ink);background:var(--zy-yellow); }
#chat .mes_text blockquote { margin-inline:0;padding:.65em 1em;background:var(--zy-yellow);border-inline-start:4px solid var(--zy-apricot);border-radius:.6rem 1.2rem .8rem .4rem;color:var(--zy-ink); }
#chat .mes_text a { color:var(--zy-focus);text-decoration:underline;text-underline-offset:.2em; }
#chat .mes_text hr { border-color:var(--zy-edge);opacity:1; }
#chat .mes_text :is(h1,h2,h3,h4) { color:var(--zy-ink);font-family:var(--zy-font);font-weight:800;line-height:1.5; }
#chat .mes_text img,
#chat .mes_text video { max-inline-size:100%;block-size:auto; }
#chat .mes_text code { color:var(--zy-ink);background:var(--zy-yellow);text-shadow:none;font-family:Consolas,monospace; }
#chat .mes_text pre { background:var(--zy-yellow);border:1px solid var(--zy-edge);border-radius:.7rem;padding:.8rem;overflow-x:auto; }
#chat .mes_text pre > code.hljs { color:var(--zy-ink);background:var(--zy-yellow);opacity:1;filter:none;text-shadow:none; }
#chat .mes_text .hljs-comment,
#chat .mes_text .hljs-quote { color:var(--zy-muted); }
#chat .mes_text .hljs-keyword,
#chat .mes_text .hljs-title,
#chat .mes_text .hljs-number { color:var(--zy-focus); }
#chat .mes_text .hljs-string,
#chat .mes_text .hljs-attr { color:var(--zy-blue); }
#chat .mes_text .code-copy { color:var(--zy-ink);background:var(--zy-paper);opacity:1;filter:none; }
#chat .mes_text table { display:block;max-inline-size:100%;overflow-x:auto; }
#chat .mes_text :is(th,td) { border-color:var(--zy-edge); }
#chat .mes_text th { background:var(--zy-yellow);color:var(--zy-ink); }
#chat .mes_text::selection,
#chat .mes_text :is(p,span,strong,em,code)::selection { color:var(--zy-paper);background:var(--zy-blue); }


/* Source: src/windows/topbar.css */
/* 只调整九个入口表面；不重排承载抽屉的 .drawer。 */
#top-bar { background:none;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none; }
#top-settings-holder { background:var(--zy-paper);border:3px solid var(--zy-yellow);border-radius:1.7rem 1rem 2rem 1.2rem;box-shadow:0 3px 0 var(--zy-edge); }
#top-settings-holder .drawer-icon { color:var(--zy-ink);opacity:1;filter:none;text-shadow:none;padding:.18rem .25rem;border-radius:.65rem; }
#top-settings-holder .drawer-icon.openIcon,
#top-settings-holder .drawer-icon:hover { color:var(--zy-focus);background:var(--zy-yellow); }
#top-settings-holder .drawer-toggle:focus-visible,
#top-settings-holder .drawer-icon:focus-visible { outline:2px solid var(--zy-focus);outline-offset:2px; }
@media(max-width:700px) {
 :root { --topBarIconSize:1.35rem;--topBarBlockPadding:1rem; }
 #top-settings-holder { border-width:2px;border-radius:1rem .7rem 1.2rem .8rem; }
 #top-settings-holder .drawer-icon { padding:.1rem; }
}


/* Source: src/windows/input.css */
#send_form { background:var(--zy-paper);border:3px solid var(--zy-yellow);border-radius:2rem 1.3rem 2.5rem 1.2rem;padding:.55rem .65rem;color:var(--zy-ink);backdrop-filter:none;box-shadow:none; }
#nonQRFormItems { align-items:center;gap:.55rem; }
#leftSendForm,
#rightSendForm { flex:0 0 auto;max-inline-size:35%; }
#send_textarea { min-inline-size:0;order:2;background:var(--zy-yellow);color:var(--zy-ink);border-radius:1.5rem 1rem 1.4rem .9rem;padding:.45rem .8rem;font-family:var(--zy-font);font-weight:600;font-size:1em;line-height:1.65;text-shadow:none;--progColor:var(--zy-blue);--progFlashColor:var(--zy-apricot);--progSuccessColor:var(--zy-blue);--progErrorColor:var(--zy-focus);--progAbortedColor:var(--zy-focus); }
#send_textarea::placeholder { color:var(--zy-muted);opacity:1; }
#send_form:has(#send_textarea:focus-visible) { outline:2px solid var(--zy-focus);outline-offset:-2px;border-color:var(--zy-edge); }
#send_form.no-connection { border-color:var(--zy-apricot); }
#leftSendForm > div,
#rightSendForm > div,
#send_form .mes_stop { color:var(--zy-ink);opacity:1;filter:none;text-shadow:none; }
#leftSendForm > div:hover,
#rightSendForm > div:hover,
#send_form .mes_stop:hover { color:var(--zy-focus);filter:none; }
#leftSendForm > div:focus-visible,
#rightSendForm > div:focus-visible { outline:2px solid var(--zy-focus);outline-offset:-2px; }
/* 原位重写纸飞机同一 ::before；不改变显示状态或停止键。 */
#send_but::before { content:'\f4ba';font-family:'Font Awesome 6 Free';font-weight:900;display:inline-block;color:var(--zy-ink);font-size:1.35em;pointer-events:none; }
#send_but:hover::before { color:var(--zy-focus); }
#options,
#extensionsMenu { background:var(--zy-paper);color:var(--zy-ink);border:2px solid var(--zy-edge);border-radius:1rem;box-shadow:none; }
#options .options-content a,
#extensionsMenu > .extension_container > div,
#extensionsMenu > div:not(.extension_container) { color:var(--zy-ink);opacity:1;filter:none; }
#options .options-content a:hover,
#extensionsMenu > .extension_container > div:hover,
#extensionsMenu > div:not(.extension_container):hover { background:var(--zy-yellow);color:var(--zy-focus); }
@media(max-width:700px) {
 :root { --bottomFormIconSize:1.35rem;--bottomFormBlockPadding:.55rem; }
 #send_form { padding:.4rem .2rem;border-width:2px;border-radius:1.2rem .8rem 1.3rem .9rem; }
 #nonQRFormItems { gap:.25rem; }
 #send_textarea { padding-inline:.5rem; }
}


